class stringx {
    void *data;
    void *reserved;
public:
    stringx(int);
    stringx(const stringx &);
    ~stringx();
};

struct HighScoreData {
    char initials[4];
    char character[32];
    int score;
    int icons;
};

struct FEMenuEntry {
    int entry_num;
};

class TextString {
public:
    void changeText(stringx);
    void changePos(float, float);
};

class PanelQuad {
public:
    void TurnOn(bool);
};

class GlobalDataClass {
public:
    HighScoreData getBeachHighScore(int, int, bool);
};

extern GlobalDataClass globalCareerData;

class HighScoreFrontEnd {
    char padding0[0x50];
    FEMenuEntry *highlighted;
    char padding1[0x10];
    void *active;
    char padding2[0xd8];
    TextString *column_labels[5];
    TextString *info[10][5];
    char padding3[0x10];
    PanelQuad *line;
    char padding4[0x14];
    float flash_timer;
public:
    enum { NUM_ROWS = 10, BEACH_LAST = 22 };
    void OnSwitchBeach();
};

__asm__(".equ globalCareerData, 0x004349B8");
__asm__(".equ getBeachHighScore__15GlobalDataClassiib, 0x002F0020");
__asm__(".equ changeText__10TextStringG7stringx, 0x001483E0");
__asm__(".equ changePos__10TextStringff, 0x00148430");
__asm__(".equ TurnOn__9PanelQuadb, 0x001D9AB0");
__asm__(".equ __7stringxi, 0x0034D5C0");
__asm__(".equ __7stringxRC7stringx, 0x0034D4D0");
__asm__(".equ _$_7stringx, 0x0034D6E0");

void HighScoreFrontEnd::OnSwitchBeach()
{
	bool icon_mode = highlighted->entry_num >= BEACH_LAST;
	HighScoreData hsd;
	for(int i=0; i<NUM_ROWS; i++)
	{
		int bn = highlighted->entry_num;
		if(icon_mode) bn -= BEACH_LAST;
		hsd = globalCareerData.getBeachHighScore(bn, i, icon_mode);
		info[i][1]->changeText(hsd.initials);
		info[i][2]->changeText(hsd.character);
		info[i][3]->changeText(stringx(hsd.score));
		if(icon_mode)
			info[i][4]->changeText(stringx(hsd.icons));
	}
	line->TurnOn(!active && icon_mode);

	// recenter the 4th column
	int center = (!icon_mode) ? 489 : 466;
	column_labels[3]->changePos(center, 101);
	for(int j=0; j<NUM_ROWS; j++)
		info[j][3]->changePos(center, 121 + j*20);

	flash_timer = 0;
}
